yakit.AutoInitYakit()

domains = cli.String("domains")
domains = str.ParseStringToLines(domains)
thread = cli.Int("thread", cli.setDefault(10))
dnsServer = cli.String("dnsServer", cli.setDefault("114.114.114.114"))
dnsServer = str.Split(dnsServer, ",")
cli.check()

wg := sync.NewSizedWaitGroup(thread)

yakit.EnableTable("结果", ["域名", "解析IP"])
outputTable = func(domain, IP) {
    data = make(map[string]var)
    data["域名"] = domain
    data["解析IP"] = IP
    yakit.TableData("结果", data)
}


parseDns = func(domain,dnsServer){
    wg.Add()
    go fn{
        defer wg.Done()
        result = dns.QueryIPAll(domain, dns.dnsServers(dnsServer...))
        IP = "解析失败"
        if len(result) >= 1{
            IP = result[0]
            for _,i = range result{
                if str.IsIPv4(i){
                    IP = i
                    break
                }
            }
        }
        outputTable(domain, IP)
    }

}



main = func(){
    log.info("任务开始：---------------------")
    for _, domain = range domains{
        parseDns(domain, dnsServer)
    }
    wg.Wait()
    log.info("任务完成：---------------------")
}
main()
